import zipfile
import xml.etree.ElementTree as ET

def read_xlsx_sheets(filepath, max_rows=20):
    """Read an xlsx file and return sheet names and first rows"""
    z = zipfile.ZipFile(filepath)

    # Read shared strings
    shared_strings = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss_tree = ET.parse(z.open('xl/sharedStrings.xml'))
        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        for si in ss_tree.findall('.//s:si', ns):
            text = ''.join(t.text or '' for t in si.findall('.//s:t', ns))
            shared_strings.append(text)

    # Read workbook to get sheet names
    wb_tree = ET.parse(z.open('xl/workbook.xml'))
    ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    sheets = []
    for sheet in wb_tree.findall('.//s:sheet', ns):
        sheets.append((sheet.get('name'), sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

    # Read relationships to map sheet ids to files
    rels_tree = ET.parse(z.open('xl/_rels/workbook.xml.rels'))
    rels_ns = {'r': 'http://schemas.openxmlformats.org/package/2006/relationships'}
    rid_to_target = {}
    for rel in rels_tree.findall('.//r:Relationship', rels_ns):
        rid_to_target[rel.get('Id')] = rel.get('Target')

    results = {}
    for sheet_name, rid in sheets:
        target = rid_to_target.get(rid)
        if target and ('xl/' + target) in z.namelist():
            sheet_tree = ET.parse(z.open('xl/' + target))
            rows = []
            for row in sheet_tree.findall('.//s:row', ns):
                row_data = []
                for cell in row.findall('s:c', ns):
                    cell_type = cell.get('t')
                    value_elem = cell.find('s:v', ns)
                    value = value_elem.text if value_elem is not None else ''
                    if cell_type == 's' and value:
                        idx = int(value)
                        value = shared_strings[idx] if idx < len(shared_strings) else value
                    row_data.append(value)
                rows.append(row_data)
                if len(rows) >= max_rows:
                    break
            results[sheet_name] = rows

    return results

# Read Trio Status
